CREATE OR REPLACE FUNCTION public.is_approved_vet(_vet uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.vet_verifications v ON v.user_id=r.user_id WHERE r.user_id=_vet AND r.role='vet' AND v.status='approved'); $$;
REVOKE ALL ON FUNCTION public.is_approved_vet(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_approved_vet(uuid) TO anon,authenticated,service_role;
CREATE TABLE public.vet_public_profiles (
 user_id uuid PRIMARY KEY REFERENCES public.profiles(id), display_name text NOT NULL CHECK(length(btrim(display_name)) BETWEEN 1 AND 100), qualifications text NOT NULL DEFAULT '' CHECK(length(qualifications)<=1000), licence text NOT NULL DEFAULT '' CHECK(length(licence)<=120), specialties text[] NOT NULL DEFAULT '{}', species text[] NOT NULL DEFAULT '{}', biography text NOT NULL DEFAULT '' CHECK(length(biography)<=2000), location text NOT NULL DEFAULT '' CHECK(length(location)<=120), languages text[] NOT NULL DEFAULT '{ha}', consultation_types text[] NOT NULL DEFAULT '{in_person}' CHECK(consultation_types <@ ARRAY['in_person','online']), fee numeric CHECK(fee>=0), currency text CHECK(currency ~ '^[A-Z]{3}$'), published boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(fee IS NULL OR currency IS NOT NULL)
);
GRANT SELECT ON public.vet_public_profiles TO anon,authenticated; GRANT INSERT,UPDATE ON public.vet_public_profiles TO authenticated; GRANT ALL ON public.vet_public_profiles TO service_role;
ALTER TABLE public.vet_public_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published approved professionals" ON public.vet_public_profiles FOR SELECT TO anon,authenticated USING(published AND public.is_approved_vet(user_id));
CREATE POLICY "Vet own professional profile" ON public.vet_public_profiles FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'vet'));
CREATE POLICY "Vet create professional profile" ON public.vet_public_profiles FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'vet') AND (NOT published OR public.is_approved_vet(auth.uid())));
CREATE POLICY "Vet edit professional profile" ON public.vet_public_profiles FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'vet')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'vet') AND (NOT published OR public.is_approved_vet(auth.uid())));
CREATE OR REPLACE FUNCTION public.care_profile_write() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.user_id<>OLD.user_id THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF cardinality(NEW.specialties)>20 OR cardinality(NEW.species)>20 OR cardinality(NEW.languages)>10 OR EXISTS(SELECT 1 FROM unnest(NEW.specialties||NEW.species||NEW.languages) x WHERE length(x)>100) THEN RAISE EXCEPTION 'invalid_profile'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER care_profile_write BEFORE INSERT OR UPDATE ON public.vet_public_profiles FOR EACH ROW EXECUTE FUNCTION public.care_profile_write();
CREATE TABLE public.care_shares (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), farmer_id uuid NOT NULL REFERENCES public.profiles(id), vet_id uuid NOT NULL REFERENCES public.profiles(id), livestock_id uuid NOT NULL, scopes text[] NOT NULL CHECK(cardinality(scopes)>0 AND scopes <@ ARRAY['livestock','health','vaccinations','treatments']), expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(farmer_id,vet_id,livestock_id), FOREIGN KEY(livestock_id,farmer_id) REFERENCES public.livestock(id,owner_id)
);
GRANT SELECT ON public.care_shares TO authenticated; GRANT ALL ON public.care_shares TO service_role;
ALTER TABLE public.care_shares ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read shares" ON public.care_shares FOR SELECT TO authenticated USING(farmer_id=auth.uid() OR (vet_id=auth.uid() AND public.is_approved_vet(auth.uid()) AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>now())));
CREATE TABLE public.care_audit (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, farmer_id uuid NOT NULL, vet_id uuid NOT NULL, livestock_id uuid NOT NULL, action text NOT NULL, record_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.care_audit TO authenticated; GRANT ALL ON public.care_audit TO service_role;
ALTER TABLE public.care_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Farmer reads care audit" ON public.care_audit FOR SELECT TO authenticated USING(farmer_id=auth.uid());
CREATE OR REPLACE FUNCTION public.care_has_share(_farmer uuid,_vet uuid,_livestock uuid,_scope text DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_approved_vet(_vet) AND EXISTS(SELECT 1 FROM public.care_shares s WHERE s.farmer_id=_farmer AND s.vet_id=_vet AND s.livestock_id=_livestock AND s.revoked_at IS NULL AND (s.expires_at IS NULL OR s.expires_at>now()) AND (_scope IS NULL OR _scope=ANY(s.scopes))); $$;
REVOKE ALL ON FUNCTION public.care_has_share(uuid,uuid,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_has_share(uuid,uuid,uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.care_set_share(_vet uuid,_livestock uuid,_scopes text[],_expires timestamptz DEFAULT NULL,_revoke boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'farmer') OR NOT EXISTS(SELECT 1 FROM public.livestock WHERE id=_livestock AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF _revoke THEN UPDATE public.care_shares SET revoked_at=now() WHERE farmer_id=auth.uid() AND vet_id=_vet AND livestock_id=_livestock RETURNING id INTO sid; ELSE IF NOT public.is_approved_vet(_vet) OR (_expires IS NOT NULL AND _expires<=now()) THEN RAISE EXCEPTION 'invalid_share'; END IF; INSERT INTO public.care_shares(farmer_id,vet_id,livestock_id,scopes,expires_at) VALUES(auth.uid(),_vet,_livestock,_scopes,_expires) ON CONFLICT(farmer_id,vet_id,livestock_id) DO UPDATE SET scopes=EXCLUDED.scopes,expires_at=EXCLUDED.expires_at,revoked_at=NULL RETURNING id INTO sid; END IF; IF sid IS NULL THEN RAISE EXCEPTION 'not_found'; END IF; INSERT INTO public.care_audit(actor_id,farmer_id,vet_id,livestock_id,action,record_id) VALUES(auth.uid(),auth.uid(),_vet,_livestock,CASE WHEN _revoke THEN 'share_revoked' ELSE 'share_granted' END,sid); RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.care_set_share(uuid,uuid,text[],timestamptz,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_set_share(uuid,uuid,text[],timestamptz,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_shared_records(_livestock uuid,_farmer uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb='{}'; BEGIN IF auth.uid() IS NULL OR NOT public.care_has_share(_farmer,auth.uid(),_livestock) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF public.care_has_share(_farmer,auth.uid(),_livestock,'livestock') THEN result=result||jsonb_build_object('livestock',(SELECT to_jsonb(l)-'owner_id' FROM public.livestock l WHERE id=_livestock AND owner_id=_farmer)); END IF; IF public.care_has_share(_farmer,auth.uid(),_livestock,'health') THEN result=result||jsonb_build_object('health',COALESCE((SELECT jsonb_agg(to_jsonb(h)-'owner_id' ORDER BY event_date DESC) FROM public.health_events h WHERE livestock_id=_livestock AND owner_id=_farmer),'[]'::jsonb)); END IF; IF public.care_has_share(_farmer,auth.uid(),_livestock,'vaccinations') THEN result=result||jsonb_build_object('vaccinations',COALESCE((SELECT jsonb_agg(to_jsonb(v)-'owner_id' ORDER BY vaccination_date DESC) FROM public.vaccination_records v WHERE livestock_id=_livestock AND owner_id=_farmer),'[]'::jsonb)); END IF; IF public.care_has_share(_farmer,auth.uid(),_livestock,'treatments') THEN result=result||jsonb_build_object('treatments',COALESCE((SELECT jsonb_agg(to_jsonb(t)-'owner_id' ORDER BY record_date DESC) FROM public.treatment_records t WHERE livestock_id=_livestock AND owner_id=_farmer),'[]'::jsonb)); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.care_shared_records(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_shared_records(uuid,uuid) TO authenticated;
CREATE TABLE public.care_slots (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vet_id uuid NOT NULL REFERENCES public.profiles(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, consultation_type text NOT NULL CHECK(consultation_type IN('online','in_person')), location text NOT NULL DEFAULT '' CHECK(length(location)<=200), published boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at AND ends_at-starts_at<=interval '4 hours'), UNIQUE(vet_id,starts_at)
);
GRANT SELECT ON public.care_slots TO anon,authenticated; GRANT INSERT,UPDATE ON public.care_slots TO authenticated; GRANT ALL ON public.care_slots TO service_role;
ALTER TABLE public.care_slots ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published vet slots" ON public.care_slots FOR SELECT TO anon,authenticated USING(published AND starts_at>now() AND public.is_approved_vet(vet_id) AND EXISTS(SELECT 1 FROM public.vet_public_profiles p WHERE p.user_id=vet_id AND p.published));
CREATE POLICY "Own vet slots" ON public.care_slots FOR SELECT TO authenticated USING(vet_id=auth.uid() AND public.is_approved_vet(auth.uid()));
CREATE POLICY "Create own vet slot" ON public.care_slots FOR INSERT TO authenticated WITH CHECK(vet_id=auth.uid() AND public.is_approved_vet(auth.uid()));
CREATE POLICY "Update own vet slot" ON public.care_slots FOR UPDATE TO authenticated USING(vet_id=auth.uid() AND public.is_approved_vet(auth.uid())) WITH CHECK(vet_id=auth.uid() AND public.is_approved_vet(auth.uid()));
CREATE OR REPLACE FUNCTION public.care_slot_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF (NEW.id,NEW.vet_id,NEW.starts_at,NEW.ends_at,NEW.consultation_type,NEW.location) IS DISTINCT FROM (OLD.id,OLD.vet_id,OLD.starts_at,OLD.ends_at,OLD.consultation_type,OLD.location) THEN RAISE EXCEPTION 'slot_immutable'; END IF; ELSE IF NEW.starts_at<=now() THEN RAISE EXCEPTION 'future_slot_required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(NEW.vet_id::text,0)); IF EXISTS(SELECT 1 FROM public.care_slots s WHERE s.vet_id=NEW.vet_id AND s.published AND s.starts_at<NEW.ends_at AND s.ends_at>NEW.starts_at) THEN RAISE EXCEPTION 'slot_conflict' USING ERRCODE='23505'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER care_slot_write BEFORE INSERT OR UPDATE ON public.care_slots FOR EACH ROW EXECUTE FUNCTION public.care_slot_write();
CREATE TABLE public.care_appointments (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), farmer_id uuid NOT NULL REFERENCES public.profiles(id), vet_id uuid NOT NULL REFERENCES public.profiles(id), livestock_id uuid NOT NULL, slot_id uuid NOT NULL REFERENCES public.care_slots(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, consultation_type text NOT NULL, location text NOT NULL, reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000), status text NOT NULL DEFAULT 'requested' CHECK(status IN('requested','confirmed','declined','cancelled','completed','no_show')), fee numeric, currency text, farmer_name text NOT NULL, vet_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(livestock_id,farmer_id) REFERENCES public.livestock(id,owner_id)
);
GRANT SELECT ON public.care_appointments TO authenticated; GRANT ALL ON public.care_appointments TO service_role;
ALTER TABLE public.care_appointments ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX care_slot_reserved ON public.care_appointments(slot_id) WHERE status IN('requested','confirmed','completed','no_show');
CREATE OR REPLACE FUNCTION public.care_can_access(_appointment uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.care_appointments a WHERE a.id=_appointment AND (a.farmer_id=auth.uid() OR (a.vet_id=auth.uid() AND public.care_has_share(a.farmer_id,a.vet_id,a.livestock_id)))); $$;
REVOKE ALL ON FUNCTION public.care_can_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_can_access(uuid) TO authenticated,service_role;
CREATE POLICY "Appointment participants" ON public.care_appointments FOR SELECT TO authenticated USING(farmer_id=auth.uid() OR (vet_id=auth.uid() AND public.care_has_share(farmer_id,vet_id,livestock_id)));
CREATE TABLE public.care_notifications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL REFERENCES public.profiles(id), appointment_id uuid REFERENCES public.care_appointments(id), kind text NOT NULL, dedupe_key text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(recipient_id,dedupe_key)
);
GRANT SELECT ON public.care_notifications TO authenticated; GRANT UPDATE(read_at) ON public.care_notifications TO authenticated; GRANT ALL ON public.care_notifications TO service_role;
ALTER TABLE public.care_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own authorized notifications" ON public.care_notifications FOR SELECT TO authenticated USING(recipient_id=auth.uid() AND (appointment_id IS NULL OR public.care_can_access(appointment_id)));
CREATE POLICY "Mark own notifications read" ON public.care_notifications FOR UPDATE TO authenticated USING(recipient_id=auth.uid() AND (appointment_id IS NULL OR public.care_can_access(appointment_id))) WITH CHECK(recipient_id=auth.uid());
CREATE OR REPLACE FUNCTION public.care_book(_slot uuid,_livestock uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.care_slots; p public.vet_public_profiles; aid uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'farmer') OR NOT EXISTS(SELECT 1 FROM public.livestock WHERE id=_livestock AND owner_id=auth.uid() AND status='active') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; SELECT * INTO s FROM public.care_slots WHERE id=_slot AND published AND starts_at>now() FOR UPDATE; IF s.id IS NULL OR NOT public.care_has_share(auth.uid(),s.vet_id,_livestock) THEN RAISE EXCEPTION 'share_required' USING ERRCODE='42501'; END IF; SELECT * INTO p FROM public.vet_public_profiles WHERE user_id=s.vet_id AND published; IF p.user_id IS NULL THEN RAISE EXCEPTION 'unavailable'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0)); IF EXISTS(SELECT 1 FROM public.care_appointments a WHERE a.farmer_id=auth.uid() AND a.status IN('requested','confirmed') AND a.starts_at<s.ends_at AND a.ends_at>s.starts_at) THEN RAISE EXCEPTION 'booking_conflict' USING ERRCODE='23505'; END IF; INSERT INTO public.care_appointments(farmer_id,vet_id,livestock_id,slot_id,starts_at,ends_at,consultation_type,location,reason,fee,currency,farmer_name,vet_name) VALUES(auth.uid(),s.vet_id,_livestock,s.id,s.starts_at,s.ends_at,s.consultation_type,s.location,btrim(_reason),p.fee,p.currency,(SELECT full_name FROM public.profiles WHERE id=auth.uid()),p.display_name) RETURNING id INTO aid; INSERT INTO public.care_notifications(recipient_id,appointment_id,kind,dedupe_key) VALUES(s.vet_id,aid,'appointment_requested',aid::text||':requested'); RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.care_book(uuid,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_book(uuid,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_transition(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.care_appointments; BEGIN SELECT * INTO a FROM public.care_appointments WHERE id=_id FOR UPDATE; IF a.id IS NULL OR NOT public.care_can_access(_id) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF _status='cancelled' AND a.status IN('requested','confirmed') THEN NULL; ELSIF auth.uid()=a.vet_id AND ((a.status='requested' AND _status IN('confirmed','declined')) OR (a.status='confirmed' AND _status IN('completed','no_show') AND a.ends_at<=now())) THEN NULL; ELSE RAISE EXCEPTION 'invalid_transition'; END IF; UPDATE public.care_appointments SET status=_status,updated_at=now() WHERE id=_id; INSERT INTO public.care_audit(actor_id,farmer_id,vet_id,livestock_id,action,record_id) VALUES(auth.uid(),a.farmer_id,a.vet_id,a.livestock_id,'appointment_'||_status,a.id); INSERT INTO public.care_notifications(recipient_id,appointment_id,kind,dedupe_key) VALUES(CASE WHEN auth.uid()=a.farmer_id THEN a.vet_id ELSE a.farmer_id END,a.id,'appointment_'||_status,a.id::text||':'||_status) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.care_transition(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_transition(uuid,text) TO authenticated;